// Companion Content Guide shell adapter: presentation snapshots, no Story mutations.
let companionGuideView=null,companionGuideImport=null,companionGuideImportAttempt=0,companionGuideContextKey='',companionGuideScopeKey='',companionGuideScopeRevision=0,companionGuideSecurityKey='',companionGuideRevision=0;
let companionGuideContext=Object.freeze({identity:'companion-context-0',revision:0,mode:'minimal'}),companionGuideScroll={x:0,y:0};
function notifyCompanionGuideContext(){
 const mode=spoilerMode(),scopeKey=JSON.stringify([spoilerScope(),currentUser?.id||null,activeStoryId,explicitSignOut,CLOUD_CONFIG.supabaseUrl||null]);
 if(scopeKey!==companionGuideScopeKey){companionGuideScopeKey=scopeKey;companionGuideScopeRevision++;}
 const securityKey=JSON.stringify([scopeKey,authGeneration,backendGeneration]);
 if(securityKey!==companionGuideSecurityKey){companionGuideSecurityKey=securityKey;companionGuideRevision++;}
 const identity='companion-scope-'+companionGuideScopeRevision,key=JSON.stringify([identity,companionGuideRevision,mode]);
 if(key!==companionGuideContextKey){
  companionGuideContextKey=key;
  companionGuideContext=Object.freeze({identity,revision:companionGuideRevision,mode});
  companionGuideView?.setContext(companionGuideContext);
 }
 return companionGuideContext;
}
function returnFromCompanionGuide(){
 const tracker=$("trackerView"),guide=$("companionGuide");if(!tracker||!guide)return;
 companionGuideView?.setOpen(false);guide.hidden=true;tracker.hidden=false;
 $("openCompanionGuide")?.focus({preventScroll:true});window.scrollTo(companionGuideScroll.x,companionGuideScroll.y);
}
async function loadCompanionGuideView(){
 const guide=$("companionGuide");if(!guide||guide.hidden)return;
 if(companionGuideView){companionGuideView.setContext(notifyCompanionGuideContext());companionGuideView.setOpen(true);companionGuideView.focus();return;}
 if(companionGuideImport)return companionGuideImport;
 guide.replaceChildren();
 const message=document.createElement('p');message.textContent='Loading Companion Content Guide…';message.setAttribute('role','status');
 const back=document.createElement('button');back.type='button';back.textContent='Return to Tracker';back.onclick=returnFromCompanionGuide;
 guide.append(message,back);back.focus({preventScroll:true});
 const path='./assets/companion-guide.js'+(companionGuideImportAttempt?'?attempt='+companionGuideImportAttempt:'');companionGuideImportAttempt++;
 companionGuideImport=import(path).then(module=>{
  companionGuideView=module.mountCompanionGuide(guide,{context:notifyCompanionGuideContext(),onReturn:returnFromCompanionGuide});
  companionGuideView.setOpen(!guide.hidden);if(!guide.hidden)companionGuideView.focus();
 }).catch(()=>{
  guide.replaceChildren();const text=document.createElement('p');text.textContent='Could not load Companion Content Guide. Tracker state is unchanged.';text.setAttribute('role','status');
  const retry=document.createElement('button');retry.type='button';retry.textContent='Retry guide';retry.onclick=()=>loadCompanionGuideView();
  guide.append(text,retry,back);if(!guide.hidden)retry.focus({preventScroll:true});
 }).finally(()=>{companionGuideImport=null;});
 return companionGuideImport;
}
function openCompanionContentGuide(){
 const tracker=$("trackerView"),guide=$("companionGuide");if(!tracker||!guide||tracker.hidden)return;
 companionGuideScroll={x:window.scrollX||0,y:window.scrollY||0};notifyCompanionGuideContext();
 tracker.hidden=true;guide.hidden=false;window.scrollTo(0,0);void loadCompanionGuideView();
}
